def is_power_of_5(N):
    if N <= 0:
        return False, None
    k = 0
    temp_N = N
    while temp_N % 5 == 0:
        temp_N //= 5
        k += 1
    if temp_N == 1:
        return True, k
    else:
        return False, None

results = {}
odd_n = list(range(3, 32, 2))

print("--- Results for odd n (3 <= n <= 31) ---")
for n in odd_n:
    X = 2**n - 3
    is_pow5, k = is_power_of_5(X)

    result_str = f"n={n}: X = {X}. "

    if is_pow5:
        if k % 2 != 0:
            result_str += f"Is a power of 5 (5^{k}). Exponent k={k} is ODD. (SOLUTION)"
        else:
            result_str += f"Is a power of 5 (5^{k}). Exponent k={k} is EVEN."
    else:
        result_str += "Not a power of 5."

    results[n] = result_str
    print(result_str)

print("\n--- Summary ---")
print(results)
